import{_ as t,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 2 Lab — Ship Your Page","description":"","frontmatter":{"source":"weeks/02-ship-your-page/lab.md"},"headers":[],"relativePath":"weeks/02-ship-your-page/lab.md","filePath":"weeks/02-ship-your-page/lab.md"}'),r={name:"weeks/02-ship-your-page/lab.md"};function n(i,e,h,l,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="week-2-lab--ship-your-page" tabindex="-1">Week 2 Lab — Ship Your Page <a class="header-anchor" href="#week-2-lab--ship-your-page" aria-label="Permalink to &quot;Week 2 Lab — Ship Your Page&quot;">​</a></h1><blockquote><p><strong>Goal:</strong> in Studio A, publish your week 1 page at <code>https://[your-username].github.io</code> and start your <code>PROMPTS.md</code> log. In Studio B, improve the page with the three habits, check its accessibility and write your own AI-use rules. <strong>Time:</strong> two 75-minute studios, with about 40 minutes of lab in Studio A and 60 in Studio B. <strong>You need:</strong> your week 1 <code>index.html</code> (on your laptop, or download it from Canvas), your GitHub account and your phone for two-factor authentication, and your week 1 scratch note.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely · 🟡 AI limited: the AI may comment or hint, but the work is yours · 🔴 AI off: close the AI tabs and work alone.</p><p>Studios are graded on effort, not polish (<a href="./../../assessment/rubrics.html#labs">rubric</a>): a part that didn&#39;t work, with the exact error and what you tried, still counts.</p><p>Stuck for more than 5 minutes? Check <a href="#troubleshooting">Troubleshooting</a>, ask a neighbor, then raise your hand. New to the GitHub website? Keep <a href="./../../setup/github-basics.html">GitHub basics</a> open alongside. Using a screen reader or only a keyboard? See the <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a>.</p><hr><h2 id="studio-a--publish-your-page-75-min" tabindex="-1">Studio A — Publish your page (75 min) <a class="header-anchor" href="#studio-a--publish-your-page-75-min" aria-label="Permalink to &quot;Studio A — Publish your page (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th><th>Time</th><th>Core or If time</th><th>AI use</th></tr></thead><tbody><tr><td>A1</td><td>Publish on GitHub Pages</td><td>30 min</td><td>Core</td><td>🟢 AI on if you get stuck</td></tr><tr><td>A2</td><td>Start <code>PROMPTS.md</code></td><td>10 min</td><td>Core</td><td>🟢 AI on for formatting · 🔴 AI off for the Ownership statement</td></tr><tr><td>A3</td><td>Make one change by hand on GitHub</td><td>5 min</td><td>If time</td><td>🔴 AI off</td></tr></tbody></table><p>Before the lab: the recap, the concept talk and a live demo (30 minutes). The studio ends with a <strong>checkpoint share</strong>: open a neighbor&#39;s page on your phone.</p><h3 id="part-a1--publish-on-github-pages-30-min" tabindex="-1">Part A1 — Publish on GitHub Pages (30 min) <a class="header-anchor" href="#part-a1--publish-on-github-pages-30-min" aria-label="Permalink to &quot;Part A1 — Publish on GitHub Pages (30 min)&quot;">​</a></h3><p><strong>Why:</strong> a page on your laptop only exists for you. On GitHub Pages it has a real address anyone can visit. GitHub stores your file in a <a href="./../../resources/glossary.html#repository"><strong>repository</strong></a> (a project folder GitHub keeps track of), and <a href="./../../resources/glossary.html#github-pages"><strong>GitHub Pages</strong></a> serves it as a website.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Your repository and your page are <strong>public</strong>, and every old version stays visible. Before you upload, read your page once more: first name or nickname only, no surname, email, phone number, address, student ID or anything about other people.</p></div><h4 id="create-the-repository-5-min" tabindex="-1">Create the repository (5 min) <a class="header-anchor" href="#create-the-repository-5-min" aria-label="Permalink to &quot;Create the repository (5 min)&quot;">​</a></h4><ol><li>Sign in to <strong>github.com</strong>. Note your exact username: click your profile picture (top right) and read the name in bold.</li><li>Click the <strong>+</strong> menu (top right, <strong>Create new…</strong>) → <strong>New repository</strong>.</li><li><strong>Owner:</strong> your username. <strong>Repository name:</strong> your username followed by <code>.github.io</code>. Example: if your username is <code>sam-rivera</code>, type <code>sam-rivera.github.io</code>. It must match exactly.</li><li>Choose <strong>Public</strong>.</li><li>Turn on <strong>Add a README file</strong> (sometimes shown as &quot;Add README&quot;).</li><li>Click <strong>Create repository</strong>.</li></ol><p>✅ <strong>Checkpoint:</strong> you see your new repository with a <code>README.md</code> file, and the name at the top is <code>[your-username]/[your-username].github.io</code>.</p><h4 id="add-indexhtml-10-min" tabindex="-1">Add <code>index.html</code> (10 min) <a class="header-anchor" href="#add-indexhtml-10-min" aria-label="Permalink to &quot;Add `index.html` (10 min)&quot;">​</a></h4><p>Pick <strong>one</strong> option.</p><p><strong>Option A: upload the file.</strong></p><ol><li>Click <strong>Add file</strong> → <strong>Upload files</strong>.</li><li>Drag <code>index.html</code> onto the page, or click <strong>choose your files</strong>.</li><li>In the <strong>Commit changes</strong> box at the bottom, type the message <code>Add home page</code>.</li><li>Click <strong>Commit changes</strong>.</li></ol><p><strong>Option B: paste the code.</strong></p><ol><li>Click <strong>Add file</strong> → <strong>Create new file</strong>.</li><li>In the name box, type <code>index.html</code>.</li><li>Click in the big editing area and paste your code.</li><li>Check the first line starts with <code>&lt;!DOCTYPE html&gt;</code> or <code>&lt;html</code> and not with <code>```</code>. Delete any <code>```</code> lines at the top or bottom.</li><li>Click <strong>Commit changes…</strong>, type the message <code>Add home page</code>, and click <strong>Commit changes</strong>.</li></ol><p>You have just made your first <a href="./../../resources/glossary.html#commit"><strong>commit</strong></a>: a saved snapshot of your project with a message saying what changed. Next week commits become your save points.</p><p>✅ <strong>Checkpoint:</strong> your repository&#39;s file list shows <code>README.md</code> and <code>index.html</code>.</p><h4 id="check-the-pages-settings-5-min" tabindex="-1">Check the Pages settings (5 min) <a class="header-anchor" href="#check-the-pages-settings-5-min" aria-label="Permalink to &quot;Check the Pages settings (5 min)&quot;">​</a></h4><p>For a repository named <code>[your-username].github.io</code>, GitHub usually switches Pages on for you. Check anyway:</p><ol><li>Click the <strong>Settings</strong> tab of your repository (top row, right).</li><li>In the left sidebar, click <strong>Pages</strong>.</li><li>Under <strong>Build and deployment</strong>, <strong>Source</strong> should say <strong>Deploy from a branch</strong>, and <strong>Branch</strong> should be <code>main</code> with the folder <code>/ (root)</code>. If not, set them and click <strong>Save</strong>.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If you can&#39;t find these settings, ask your assistant: &quot;Where are the GitHub Pages settings for a repository, as of today?&quot; and compare its answer with what you see.</p></div><h4 id="visit-your-live-site-10-min" tabindex="-1">Visit your live site (10 min) <a class="header-anchor" href="#visit-your-live-site-10-min" aria-label="Permalink to &quot;Visit your live site (10 min)&quot;">​</a></h4><ol><li>Wait one or two minutes. To watch progress, open the <strong>Actions</strong> tab: a run called <strong>pages build and deployment</strong> shows a yellow dot while it works and a green check when it&#39;s done. Don&#39;t re-upload while you wait.</li><li>Back in <strong>Settings → Pages</strong>, a message appears at the top: <strong>Your site is live at…</strong> with a <strong>Visit site</strong> button.</li><li>Open <code>https://[your-username].github.io</code>. The address is all lowercase, even if your username has capitals.</li><li>Open the same address on your phone. Click your fun-fact button there too.</li><li>Post your URL where your instructor asks (for example the class chat) for Studio B&#39;s gallery walk.</li></ol><p>✅ <strong>Checkpoint:</strong> your page, with your week 1 hand changes, loads at <code>https://[your-username].github.io</code> on your laptop and your phone.</p><h3 id="part-a2--start-promptsmd-10-min" tabindex="-1">Part A2 — Start <code>PROMPTS.md</code> (10 min) <a class="header-anchor" href="#part-a2--start-promptsmd-10-min" aria-label="Permalink to &quot;Part A2 — Start `PROMPTS.md` (10 min)&quot;">​</a></h3><p><strong>Why:</strong> every project in this course keeps a log of how you used AI. It shows your process, and it&#39;s part of your grade. It&#39;s written in <a href="./../../resources/glossary.html#markdown"><strong>Markdown</strong></a>, a simple text format where <code>#</code> makes a heading and <code>-</code> makes a bullet point.</p><ol><li>Open the <a href="./../../templates/PROMPTS.html">PROMPTS.md template</a> in a new tab and copy its text. On the course website, use the copy button on the template&#39;s copy block. On GitHub, use <strong>Copy raw file</strong> (two overlapping squares, top right of the file).</li><li>In your repository, click <strong>Add file</strong> → <strong>Create new file</strong>. Name it <code>PROMPTS.md</code>, and paste the template.</li><li>Fill in, using your week 1 scratch note (🟢 AI on for formatting; the content is yours): <ul><li><strong>Project</strong> and <strong>Tools used:</strong> for example <code>Home page</code> and <code>Gemini (Canvas tool), GitHub website</code>.</li><li><strong>At least two log entries:</strong> your first prompt from week 1, and the customization prompt that worked best (or went most wrong). For each: the date, what happened, and what you checked yourself. For <strong>Commit</strong>, write <code>Add home page</code>. Delete the template sections you don&#39;t need yet (you&#39;ll meet the Goldfish test and <code>AGENTS.md</code> later); keep the Ownership statement.</li><li><strong>Ownership statement</strong> (🔴 AI off, your own words): your week 1 hand changes and the feature you wrote by hand, each with what it does.</li></ul></li><li>Commit with the message <code>Start PROMPTS.md</code>, then click the file to see it formatted.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>With Gemini&#39;s Keep Activity off you can&#39;t reopen or share old chats, so copy each prompt that matters into <code>PROMPTS.md</code> (or your scratch note) as you go. If you use a tool that can make a <strong>share link</strong> to a chat, you may paste that link into an entry too, but only for chats with nothing personal in them: anyone with the link can read the chat.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Your repository is public, so <code>PROMPTS.md</code> is public too. Never paste passwords, keys or personal information into it.</p></div><p>✅ <strong>Checkpoint:</strong> <code>PROMPTS.md</code> is in your repository with a &quot;Tools used&quot; line, at least two log entries and your Ownership statement. The rest of the entries can wait for homework.</p><h3 id="part-a3--make-one-change-by-hand-on-github-5-min-if-time" tabindex="-1">Part A3 — Make one change by hand on GitHub (5 min, if time) <a class="header-anchor" href="#part-a3--make-one-change-by-hand-on-github-5-min-if-time" aria-label="Permalink to &quot;Part A3 — Make one change by hand on GitHub (5 min, if time)&quot;">​</a></h3><p>🔴 AI off. This is how you&#39;ll publish every change from now on.</p><ol><li>In your repository, click <code>index.html</code>, then the <strong>pencil</strong> icon (<strong>Edit this file</strong>).</li><li>Make one small change: a word in a heading, or a new item in a list.</li><li>Click <strong>Commit changes…</strong>, write a message that says what changed (for example <code>Rename About section</code>), and commit.</li><li>Wait a minute, then refresh your live site. Change not showing? <a href="./../../resources/glossary.html#hard-reload">Hard-reload</a>: <strong>Ctrl+Shift+R</strong> (Windows, ChromeOS) or <strong>Cmd+Shift+R</strong> (Mac).</li><li>Add the change to your Ownership statement.</li></ol><p>✅ <strong>Checkpoint:</strong> your live page shows the change, and the repository&#39;s commit history (click <strong>Commits</strong>, with the clock icon) lists it with your message.</p><h3 id="checkpoint-share-end-of-studio-a" tabindex="-1">Checkpoint share (end of Studio A) <a class="header-anchor" href="#checkpoint-share-end-of-studio-a" aria-label="Permalink to &quot;Checkpoint share (end of Studio A)&quot;">​</a></h3><p>Swap URLs with a neighbor and open each other&#39;s page on your phones. Check one thing for them: does the button work on a phone? Stuck? Share the exact blocker instead: that counts too.</p><p><strong>Working alone?</strong> Open your page in a private browser window and on your phone, and write one sentence in <code>PROMPTS.md</code> about anything that looked different.</p><hr><h2 id="studio-b--habits-access-and-your-rules-75-min" tabindex="-1">Studio B — Habits, access and your rules (75 min) <a class="header-anchor" href="#studio-b--habits-access-and-your-rules-75-min" aria-label="Permalink to &quot;Studio B — Habits, access and your rules (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th><th>Time</th><th>Core or If time</th><th>AI use</th></tr></thead><tbody><tr><td>B1</td><td>Practice the three habits</td><td>25 min</td><td>Core</td><td>🟢 AI on</td></tr><tr><td>B2</td><td>Check your page&#39;s accessibility</td><td>20 min</td><td>Core</td><td>🟢 AI on for the review</td></tr><tr><td>B3</td><td>Write your personal AI-use rules</td><td>15 min</td><td>Core</td><td>🔴 AI off</td></tr><tr><td>B4</td><td>Catch up, or start the homework</td><td>any spare time</td><td>If time</td><td>🟢 AI on</td></tr></tbody></table><p>The studio opens with a gallery walk of everyone&#39;s live page, and ends with the Week 2 exit ticket (🔴 AI off).</p><p><strong>Page not live yet?</strong> Finishing Part A1 comes first; ask for help now. You can do B1 and B2 on your saved file and publish afterwards.</p><h3 id="part-b1--practice-the-three-habits-25-min" tabindex="-1">Part B1 — Practice the three habits (25 min) <a class="header-anchor" href="#part-b1--practice-the-three-habits-25-min" aria-label="Permalink to &quot;Part B1 — Practice the three habits (25 min)&quot;">​</a></h3><p>🟢 AI on.</p><p><strong>Why:</strong> students in a Fall 2026 AI-coding course at Carnegie Mellon named three habits as their most useful practices (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU 15-113 report</a>). They work in every tool you&#39;ll use in this course.</p><blockquote><p><strong>The three habits</strong></p><ol><li><strong>Ask me questions first.</strong> Before the AI builds, have it ask you what it needs to know. Otherwise it fills the gaps with guesses.</li><li><strong>Show, don&#39;t describe.</strong> A quick sketch, or a screenshot with the problem circled, says more than a paragraph.</li><li><strong>Say what works before asking for a change.</strong> Name what must stay the same, so the AI doesn&#39;t &quot;improve&quot; it away.</li></ol></blockquote><p>More examples are in <a href="./../../resources/prompt-patterns.html#the-three-habits">Prompt Patterns</a>. You&#39;ll use all three to add <strong>one new section</strong> to your page. Pick an idea with nothing personal in it: &quot;Now&quot; (what you&#39;re up to this month), &quot;Favorite places to visit&quot;, &quot;Books I liked&quot;, &quot;Things I want to build&quot;.</p><ol><li><p><strong>Get your current code.</strong> On GitHub, open <code>index.html</code> and click <strong>Copy raw file</strong> (the icon of two overlapping squares, top right of the code). This version has all your hand changes; a chat may not.</p></li><li><p><strong>Ask me questions first.</strong> Start a new chat (with Gemini&#39;s Canvas tool on) and send:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add a new section to my home page: [section idea].</span></span>\n<span class="line"><span>Context: Here is my current page: [paste the complete index.html]</span></span>\n<span class="line"><span>Constraints: Before you write any code, ask me up to 5 questions about what I want in this section. Ask one question at a time and wait for my answer. Then summarize my answers in 3 bullet points and wait for me to say &quot;go&quot;.</span></span>\n<span class="line"><span>Done when: You have asked your questions and I have confirmed your summary.</span></span></code></pre></div><p>Answer each question yourself. &quot;Whatever you think&quot; is not an answer: each one is a decision about <em>your</em> page.</p></li><li><p><strong>Show, don&#39;t describe.</strong> On paper, sketch how the section should look: boxes for each part, with the real headings written in. Take a photo, <strong>crop it</strong> so only the sketch shows, and attach it with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Here is a sketch of how I want the new section laid out. The words on the sketch are the real headings. Follow the arrangement in the sketch; don&#39;t build anything yet.</span></span></code></pre></div><p>Anything in a picture goes to the AI company, so no faces, names or other tabs. If your tool can&#39;t take images, describe the sketch as a list instead (&quot;left: a heading; right: three cards in a row&quot;).</p></li><li><p><strong>Say what works, then ask for the change.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before you change anything: the heading, the colors, both buttons and the changes I made by hand all work. Keep them exactly as they are.</span></span>\n<span class="line"><span>Goal: Add the new section we agreed on.</span></span>\n<span class="line"><span>Constraints: One HTML file. Change only what the new section needs. Give me the complete file in one code block.</span></span>\n<span class="line"><span>Done when: The new section appears below [an existing section], matches my sketch, and everything else looks and works exactly as before.</span></span></code></pre></div></li><li><p><strong>Check it</strong> against the &quot;Done when&quot;, including your hand changes and both buttons. Then publish: on GitHub, open <code>index.html</code>, click the <strong>pencil</strong> icon, select all (<strong>Ctrl+A</strong> / <strong>Cmd+A</strong>), paste the new code, click <strong>Commit changes…</strong>, write <code>Add [section] section</code>, and commit.</p></li><li><p>In <code>PROMPTS.md</code> (or your scratch note), write which habit changed the result most, and how.</p></li></ol><p>✅ <strong>Checkpoint:</strong> your live page has the new section, everything else is unchanged, and your note says which habit helped most.</p><h3 id="part-b2--check-your-pages-accessibility-20-min" tabindex="-1">Part B2 — Check your page&#39;s accessibility (20 min) <a class="header-anchor" href="#part-b2--check-your-pages-accessibility-20-min" aria-label="Permalink to &quot;Part B2 — Check your page&#39;s accessibility (20 min)&quot;">​</a></h3><p>🟢 AI on for the review.</p><p><strong>Why:</strong> <a href="./../../resources/glossary.html#accessibility">accessibility</a> means people who use a screen reader, a keyboard instead of a mouse, zoom or high-contrast settings can use your page too. On a one-file page most problems take a minute to fix.</p><p>Run these checks on your <strong>live</strong> page and note every problem you find:</p><ol><li><p><strong>Keyboard.</strong> Click in the browser&#39;s address bar, then press <strong>Tab</strong> repeatedly. Can you reach both buttons? Can you always see where you are (a visible outline, called the <strong>focus</strong>)? Does <strong>Enter</strong> or <strong>Space</strong> press the button?</p></li><li><p><strong>Zoom.</strong> Press <strong>Ctrl</strong> and <strong>+</strong> (Mac: <strong>Cmd</strong> and <strong>+</strong>) until the page is at 200%. Does anything overlap, get cut off or scroll sideways?</p></li><li><p><strong>Structure.</strong> In the code, check:</p><table tabindex="0"><thead><tr><th>Check</th><th>What good looks like</th></tr></thead><tbody><tr><td>Language</td><td>The first lines include <code>&lt;html lang=&quot;en&quot;&gt;</code> (or your page&#39;s language)</td></tr><tr><td>Title</td><td>There&#39;s a <code>&lt;title&gt;</code> that names the page</td></tr><tr><td>Headings</td><td>Exactly one <code>&lt;h1&gt;</code>; sections use <code>&lt;h2&gt;</code>, in order</td></tr><tr><td>Buttons</td><td>Things you click are real <code>&lt;button&gt;</code> elements, not clickable <code>&lt;div&gt;</code>s (a real button works with the keyboard for free)</td></tr><tr><td>Images</td><td>Any <code>&lt;img&gt;</code> has <a href="./../../resources/glossary.html#alt-text">alt text</a>, <code>alt=&quot;…&quot;</code> (or <code>alt=&quot;&quot;</code> if it&#39;s only decoration)</td></tr><tr><td>Motion</td><td>Any animation respects &quot;reduce motion&quot; settings</td></tr></tbody></table></li><li><p><strong>Ask for a review.</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Review my page for accessibility problems.</span></span>\n<span class="line"><span>Context: Here is my page: [paste the complete code]. I&#39;m new to web development.</span></span>\n<span class="line"><span>Constraints: Don&#39;t rewrite the page. List at most five problems, most important first, each with the line it&#39;s on and a one-sentence fix. Include color contrast: is all text readable against its background?</span></span>\n<span class="line"><span>Done when: I have a short list I can check and fix one at a time.</span></span></code></pre></div><p>Don&#39;t take the list on trust: for each problem, find the line it names and decide whether it&#39;s real. For contrast, you can also check two colors with the free <a href="https://webaim.org/resources/contrastchecker/" target="_blank" rel="noreferrer">WebAIM contrast checker</a>.</p></li><li><p><strong>Fix at least one problem by hand</strong> and commit it as <code>Fix accessibility: [what you fixed]</code>. Many fixes are a single attribute or color. Keep the rest of the list for homework.</p></li></ol><p>The <a href="./../../resources/accessibility.html#making-your-own-pages-accessible">Screen reader and keyboard guide</a> has more checks for your own pages.</p><p>✅ <strong>Checkpoint:</strong> you have a written list of problems, and at least one fix is committed.</p><h3 id="part-b3--write-your-personal-ai-use-rules-15-min" tabindex="-1">Part B3 — Write your personal AI-use rules (15 min) <a class="header-anchor" href="#part-b3--write-your-personal-ai-use-rules-15-min" aria-label="Permalink to &quot;Part B3 — Write your personal AI-use rules (15 min)&quot;">​</a></h3><p>🔴 AI off. Close the AI tabs.</p><p><strong>Why:</strong> the course has rules about AI use (the 🟢 AI on, 🟡 AI limited and 🔴 AI off labels). Inside them, you decide how <em>you</em> want to use it. In one study, students who had written their own rules for using AI did better than those who hadn&#39;t (<a href="https://arxiv.org/abs/2609.16784" target="_blank" rel="noreferrer">Azimi, 2026</a>). You&#39;ll revise these rules in week 16 and see what changed.</p><p>Write <strong>4 to 6 rules</strong>, each one sentence, in the form &quot;When…, I will…&quot; or &quot;I will not…&quot;. Cover:</p><ul><li>one thing you&#39;re happy to use AI for, and why;</li><li>one thing you&#39;ll do yourself even when AI could (and why it matters to you);</li><li>how you&#39;ll check AI&#39;s work before you trust it;</li><li>what you will never paste into an AI tool;</li><li>what you&#39;ll do when you&#39;re stuck or frustrated (the two-strikes rule, a break, asking a person);</li><li>optional: a rule about time, or about free-tier limits.</li></ul><p>An example of the form, not a rule to copy: <em>&quot;When the AI writes code I can&#39;t explain, I will ask it to walk me through it before I commit.&quot;</em></p><p>Submit your rules on <strong>Canvas</strong>, the course&#39;s learning management system (not Gemini&#39;s Canvas tool), as the assignment &quot;Personal AI-use rules v1&quot;. Not in your repository: they&#39;re personal writing. There are no wrong rules; they&#39;re scored for completion. Not finished? Submit them before next week&#39;s Studio A.</p><p>✅ <strong>Checkpoint:</strong> your 4–6 rules are submitted on Canvas.</p><h3 id="part-b4--catch-up-or-start-the-homework-if-time" tabindex="-1">Part B4 — Catch up, or start the homework (if time) <a class="header-anchor" href="#part-b4--catch-up-or-start-the-homework-if-time" aria-label="Permalink to &quot;Part B4 — Catch up, or start the homework (if time)&quot;">​</a></h3><ul><li><strong>Behind?</strong> Finish A1 (a live page) first, then A2 and B3. Ask for help now rather than at home.</li><li><strong>Done?</strong> Start homework task 1, the Projects section (<a href="./homework.html">homework</a>), or fix the next item on your accessibility list.</li></ul><h3 id="before-you-leave-studio-b" tabindex="-1">Before you leave Studio B <a class="header-anchor" href="#before-you-leave-studio-b" aria-label="Permalink to &quot;Before you leave Studio B&quot;">​</a></h3><ul><li>☐ Your live URL works and is posted for the gallery walk.</li><li>☐ <code>index.html</code> and <code>PROMPTS.md</code> are in your <code>[your-username].github.io</code> repository.</li><li>☐ Your personal AI-use rules are on Canvas.</li><li>☐ You did the Week 2 exit ticket (🔴 AI off). It&#39;s scored for completion, not correctness.</li><li>☐ You know what&#39;s in the <a href="./homework.html">homework</a>, including the rest of the AI Fluency course.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>404 — There isn&#39;t a GitHub Pages site here</code></td><td>Not deployed yet</td><td>Wait 2 minutes, then refresh. Check the <strong>Actions</strong> tab for a green check</td></tr><tr><td>Still 404 after 5 minutes</td><td>Repository name wrong</td><td><strong>Settings → General → Repository name</strong> must be exactly <code>[your-username].github.io</code>. Rename it, then wait again</td></tr><tr><td>Still 404, name is right</td><td>File name, location or settings</td><td>The file must be <code>index.html</code>, lowercase, at the top level (not in a folder). Check <strong>Settings → Pages</strong> and that the repository is <strong>Public</strong></td></tr><tr><td>The site shows your README text instead of your page</td><td><code>index.html</code> is missing or misnamed</td><td>Check the file list; rename the file if needed (open it, pencil icon, edit the name)</td></tr><tr><td>The site shows raw code as text</td><td>Wrong file name, or chat formatting pasted in</td><td>Make sure the name ends in <code>.html</code>; delete any <code>```</code> lines at the top and bottom</td></tr><tr><td>Extra files such as <code>index (1).html</code></td><td>Uploaded twice while Pages was deploying</td><td>Delete the extra file (open it, <strong>…</strong> menu, <strong>Delete file</strong>, commit)</td></tr><tr><td>The live site looks different from the preview</td><td>The preview loaded something your file doesn&#39;t include</td><td>Ask the AI to &quot;put everything in one file with no external files or images&quot;, then update <code>index.html</code></td></tr><tr><td>Your change doesn&#39;t show on the live site</td><td>Not deployed yet, or the browser remembers the old page</td><td>Wait a minute, then hard-reload: <strong>Ctrl+Shift+R</strong> (Windows, ChromeOS) or <strong>Cmd+Shift+R</strong> (Mac)</td></tr><tr><td>You already have a <code>[your-username].github.io</code> repository</td><td>From an earlier project</td><td>Reuse it: rename the old <code>index.html</code> to <code>old-index.html</code>, then upload the new one</td></tr><tr><td>GitHub won&#39;t let you create a public repository or turn on Pages</td><td>The account is managed by a school or employer</td><td>Use a personal GitHub account</td></tr><tr><td>The AI&#39;s new version lost your hand changes</td><td>It started from an older copy</td><td>Copy the raw file from GitHub, paste it in, and use habit 3</td></tr><tr><td>The AI can&#39;t read your sketch</td><td>Some tools or free plans don&#39;t take images</td><td>Describe the sketch as a list (&quot;top: heading; below: three cards in a row&quot;)</td></tr><tr><td>You hit a usage limit in the assistant</td><td>Free tiers have limits (see the <a href="./../../TOOLS.html">Tool Handout</a>)</td><td>Switch to a fallback and paste in your current code. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr></tbody></table><p>More fixes: <a href="./../../resources/troubleshooting.html">Troubleshooting</a>, including <a href="./../../resources/troubleshooting.html#github-pages-shows-404">GitHub Pages shows 404</a>.</p><h2 id="if-your-tool-is-down" tabindex="-1">If your tool is down <a class="header-anchor" href="#if-your-tool-is-down" aria-label="Permalink to &quot;If your tool is down&quot;">​</a></h2><ul><li><strong>GitHub or Pages:</strong> check <a href="https://www.githubstatus.com" target="_blank" rel="noreferrer">githubstatus.com</a>. Do Studio B on your saved file and publish later.</li><li><strong>The chat assistant:</strong> switch to a fallback in the <a href="./../../TOOLS.html">Tool Handout</a>: <strong>Claude (Artifacts)</strong> has a live preview (18+ only); <strong>ChatGPT</strong> gives code you run yourself (<a href="./../01-hello-vibe-coding/lab.html#no-preview-run-it-yourself">No preview? Run it yourself</a>). Paste your current code into the new chat first: the new tool starts with an empty context window.</li></ul>',80)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
